lizeAccount() {
        try {
            const { data: { session }, error: sessionError } = await supabase.auth.getSession();
            if (sessionError) throw sessionError;
            logTurboAuthDiagnostic(`sessionPresent=${Boolean(session?.user)}`);
            logTurboAuthDiagnostic(`sessionProjectMatches=${sessionMatchesConfiguredProject(session)}`);

            // Register the listener regardless of whether getSession found an
            // existing account. This keeps sign-in, profile metadata updates,
            // and sign-out reactive throughout the lifetime of the game.
            if (!this.authUnsubscribe) {
                this.authUnsubscribe = supabase.auth.onAuthStateChange((event, currentSession) => {
                    this.handleAuthStateChange(event, currentSession);
                })?.data?.subscription || null;
            }

            if (session?.user) {
                this.applyAuthenticatedSession(session);
                return;
            }

            // Guests go straight to the game setup screen. A player can sign in
            // there through the account dock whenever they want to save results.
            this.authLoading = false;
            this.screen = 'setup';
            this.setupLobby();
        } catch (error) {
            this.authLoading = false;
            this.authError = '';
            this.screen = 'setup';
            this.setupLobby();
        }
    }

